//! Deterministic packages and default hooks required by emitted LaTeX.

use crate::config::Config;
use crate::latex::emit::Usage;
use crate::math::latex_source::{macro_arity, macros_from_config};

/// Emits packages and guarded writer hooks in the documented dependency order.
pub fn preamble(usage: &Usage, config: &Config) -> String {
    let mut output = String::from(concat!(
        "% generated by writer: the packages and default hooks this body uses (no styling)\n",
        "\\makeatletter\n\\usepackage{iftex}\n\\ifPDFTeX\n",
        "  \\@ifpackageloaded{fontenc}{}{\\usepackage[T1]{fontenc}}\n",
        "  \\@ifpackageloaded{inputenc}{}{\\usepackage[utf8]{inputenc}}\n",
        "  \\usepackage{textcomp}\n",
    ));
    if !usage.newunicodechar.is_empty() {
        output.push_str("  \\usepackage{newunicodechar}\n");
        for (character, command) in &usage.newunicodechar {
            output.push_str(&format!(
                "  \\newunicodechar{{{character}}}{{\\ensuremath{{{command}}}}}\n",
            ));
        }
    }
    output.push_str(concat!(
        "\\else\n",
        "  \\@ifpackageloaded{fontspec}{}{\\usepackage{fontspec}}\n",
        "\\fi\n",
    ));
    for (needed, package) in [
        (usage.graphics, "graphicx"),
        (usage.longtable, "longtable"),
        (usage.table && config.latex.booktabs, "booktabs"),
        (usage.table, "array"),
        (usage.caption, "caption"),
        (usage.math, "amsmath,amssymb"),
    ] {
        if needed {
            output.push_str(&format!("\\usepackage{{{package}}}\n"));
        }
    }
    for package in &usage.math_packages {
        output.push_str(&format!("\\usepackage{{{package}}}\n"));
    }
    for (needed, package) in [
        (usage.color, "xcolor"),
        (usage.code, "fancyvrb"),
        (usage.listings, "listings"),
    ] {
        if needed {
            output.push_str(&format!("\\usepackage{{{package}}}\n"));
        }
    }
    if usage.ulem {
        output.push_str(
            "\\@ifpackageloaded{ulem}{}{\\usepackage[normalem]{ulem}}\n",
        );
    }
    output.push_str("\\usepackage{hyperref}\n");
    if config.latex.cleveref {
        output.push_str("\\usepackage{cleveref}\n");
    }
    if usage.highlighted {
        output.push_str("\\DefineVerbatimEnvironment{writercode}{Verbatim}{commandchars=\\\\\\{\\}}\n");
    }
    for (class, colour, style) in [
        ("Comment", "969896", Some("textit")),
        ("String", "183691", None),
        ("Number", "0086B3", None),
        ("Constant", "0086B3", None),
        ("Operator", "A71D5D", Some("textbf")),
        ("Preproc", "323232", None),
        ("Attribute", "795DA3", None),
        ("Keyword", "A71D5D", Some("textbf")),
        ("Type", "A71D5D", Some("textbf")),
        ("Function", "795DA3", Some("textbf")),
        ("Variable", "323232", None),
        ("Error", "B52A1D", Some("textbf")),
    ] {
        let text = style
            .map_or_else(|| "#1".into(), |style| format!("\\{style}{{#1}}"));
        output.push_str(&format!(
            "\\providecommand{{\\Wr{class}}}[1]{{\\textcolor[HTML]{{{colour}}}{{{text}}}}}\n",
        ));
    }
    if usage.listing_caption {
        output.push_str("\\@ifundefined{c@writerlisting}{\\DeclareCaptionType{writerlisting}[Listing][List of Listings]}{}\n");
        if config.latex.cleveref {
            output.push_str(concat!(
                "\\crefname{writerlisting}{listing}{listings}\n",
                "\\Crefname{writerlisting}{Listing}{Listings}\n",
            ));
        }
    }
    if usage.uncaptioned_longtable {
        output.push_str("\\@ifundefined{c@none}{\\newcounter{none}}{}\n");
    }
    output.push_str(DEFAULT_HOOKS);
    if let Some(depth) = usage.secnumdepth {
        output.push_str(&format!("\\setcounter{{secnumdepth}}{{{depth}}}\n"));
    }
    if let Some(depth) = usage.tocdepth {
        output.push_str(&format!("\\setcounter{{tocdepth}}{{{depth}}}\n"));
    }
    if usage.math {
        for (name, replacement) in
            macros_from_config(&config.math.katex_options)
        {
            let valid = name.strip_prefix('\\').is_some_and(|name| {
                !name.is_empty()
                    && name.bytes().all(|byte| byte.is_ascii_alphabetic())
            });
            if !valid {
                continue;
            }
            let count = macro_arity(&replacement);
            let arguments = if count == 0 {
                String::new()
            } else {
                format!("[{count}]")
            };
            output.push_str(&format!(
                "\\providecommand{{{name}}}{arguments}{{{replacement}}}\n"
            ));
        }
    }
    output.push_str("\\makeatother\n");
    output
}

const DEFAULT_HOOKS: &str = r"\providecommand{\tightlist}{\setlength{\itemsep}{0pt}\setlength{\parskip}{0pt}}
\providecommand{\writerpagebreak}{\clearpage}
\providecommand{\writerhrule}{\begin{center}\rule{0.5\linewidth}{0.4pt}\end{center}}
\providecommand{\writernotoc}{\let\writer@acl\addcontentsline\def\addcontentsline##1##2##3{\let\addcontentsline\writer@acl}}
\AtBeginDocument{%
  \@ifundefined{writercallout}{%
    \newenvironment{writercallout}[2]{\par\medskip\noindent\begin{minipage}{\linewidth}\textbf{#2}\par\nobreak}{\end{minipage}\par\medskip}}{}%
  \@ifundefined{writercell}{%
    \newenvironment{writercell}[2]{\par\medskip\noindent\textbf{\texttt{#1[#2]:}}\par\nobreak}{\par\medskip}}{}%
}
";

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::LatexEngine;
    use serde_json::json;

    // The unconditional lines are the independent §3.2 contract, including
    // defaults that must be legal before a template overrides them.
    const MINIMAL: &str = r"% generated by writer: the packages and default hooks this body uses (no styling)
\makeatletter
\usepackage{iftex}
\ifPDFTeX
  \@ifpackageloaded{fontenc}{}{\usepackage[T1]{fontenc}}
  \@ifpackageloaded{inputenc}{}{\usepackage[utf8]{inputenc}}
  \usepackage{textcomp}
\else
  \@ifpackageloaded{fontspec}{}{\usepackage{fontspec}}
\fi
\usepackage{hyperref}
\providecommand{\WrComment}[1]{\textcolor[HTML]{969896}{\textit{#1}}}
\providecommand{\WrString}[1]{\textcolor[HTML]{183691}{#1}}
\providecommand{\WrNumber}[1]{\textcolor[HTML]{0086B3}{#1}}
\providecommand{\WrConstant}[1]{\textcolor[HTML]{0086B3}{#1}}
\providecommand{\WrOperator}[1]{\textcolor[HTML]{A71D5D}{\textbf{#1}}}
\providecommand{\WrPreproc}[1]{\textcolor[HTML]{323232}{#1}}
\providecommand{\WrAttribute}[1]{\textcolor[HTML]{795DA3}{#1}}
\providecommand{\WrKeyword}[1]{\textcolor[HTML]{A71D5D}{\textbf{#1}}}
\providecommand{\WrType}[1]{\textcolor[HTML]{A71D5D}{\textbf{#1}}}
\providecommand{\WrFunction}[1]{\textcolor[HTML]{795DA3}{\textbf{#1}}}
\providecommand{\WrVariable}[1]{\textcolor[HTML]{323232}{#1}}
\providecommand{\WrError}[1]{\textcolor[HTML]{B52A1D}{\textbf{#1}}}
\providecommand{\tightlist}{\setlength{\itemsep}{0pt}\setlength{\parskip}{0pt}}
\providecommand{\writerpagebreak}{\clearpage}
\providecommand{\writerhrule}{\begin{center}\rule{0.5\linewidth}{0.4pt}\end{center}}
\providecommand{\writernotoc}{\let\writer@acl\addcontentsline\def\addcontentsline##1##2##3{\let\addcontentsline\writer@acl}}
\AtBeginDocument{%
  \@ifundefined{writercallout}{%
    \newenvironment{writercallout}[2]{\par\medskip\noindent\begin{minipage}{\linewidth}\textbf{#2}\par\nobreak}{\end{minipage}\par\medskip}}{}%
  \@ifundefined{writercell}{%
    \newenvironment{writercell}[2]{\par\medskip\noindent\textbf{\texttt{#1[#2]:}}\par\nobreak}{\par\medskip}}{}%
}
\makeatother
";

    #[test]
    fn empty_usage_has_exact_portable_defaults_without_optional_packages() {
        let usage = Usage::default();
        let mut config = Config::default();
        assert_eq!(preamble(&usage, &config), MINIMAL);
        // The font branch belongs to the .tex file, so choosing a compiler
        // never removes the other branch or changes the default hooks.
        config.latex.engine = LatexEngine::Xelatex;
        assert_eq!(preamble(&usage, &config), MINIMAL);
        config.latex.engine = LatexEngine::Lualatex;
        assert_eq!(preamble(&usage, &config), MINIMAL);
    }

    #[test]
    fn combined_requirements_keep_dependency_order_and_guard_option_bearing_loads()
     {
        let usage = Usage {
            graphics: true,
            longtable: true,
            table: true,
            caption: true,
            math: true,
            math_packages: vec!["stmaryrd", "cancel"],
            color: true,
            code: true,
            highlighted: true,
            listings: true,
            ulem: true,
            listing_caption: true,
            uncaptioned_longtable: true,
            newunicodechar: vec![('′', "'"), ('≥', r"\geq")],
            secnumdepth: Some(0),
            tocdepth: Some(-1),
            ..Usage::default()
        };
        let mut config = Config::default();
        config.latex.cleveref = true;
        let output = preamble(&usage, &config);
        let packages = output
            .lines()
            .map(str::trim_start)
            .filter(|line| line.starts_with(r"\usepackage"))
            .collect::<Vec<_>>();
        assert_eq!(
            packages,
            [
                r"\usepackage{iftex}", r"\usepackage{textcomp}",
                r"\usepackage{newunicodechar}", r"\usepackage{graphicx}",
                r"\usepackage{longtable}", r"\usepackage{booktabs}",
                r"\usepackage{array}", r"\usepackage{caption}",
                r"\usepackage{amsmath,amssymb}", r"\usepackage{stmaryrd}",
                r"\usepackage{cancel}", r"\usepackage{xcolor}",
                r"\usepackage{fancyvrb}", r"\usepackage{listings}",
                r"\usepackage{hyperref}", r"\usepackage{cleveref}",
            ]
        );
        assert!(output.contains(concat!(
            "  \\newunicodechar{′}{\\ensuremath{'}}\n",
            "  \\newunicodechar{≥}{\\ensuremath{\\geq}}\n\\else\n",
        )));
        for line in [
            r"\@ifpackageloaded{fontenc}{}{\usepackage[T1]{fontenc}}",
            r"\@ifpackageloaded{inputenc}{}{\usepackage[utf8]{inputenc}}",
            r"\@ifpackageloaded{ulem}{}{\usepackage[normalem]{ulem}}",
            r"\DefineVerbatimEnvironment{writercode}{Verbatim}{commandchars=\\\{\}}",
            r"\@ifundefined{c@writerlisting}{\DeclareCaptionType{writerlisting}[Listing][List of Listings]}{}",
            r"\@ifundefined{c@none}{\newcounter{none}}{}",
        ] {
            assert_eq!(output.matches(line).count(), 1, "{line}");
        }
        assert!(output.contains(concat!(
            "\\crefname{writerlisting}{listing}{listings}\n",
            "\\Crefname{writerlisting}{Listing}{Listings}\n",
        )));
        assert!(output.ends_with(concat!(
            "\\setcounter{secnumdepth}{0}\n",
            "\\setcounter{tocdepth}{-1}\n\\makeatother\n",
        )));
        assert!(
            output.find(r"\usepackage{cleveref}").unwrap()
                < output.find(r"\DefineVerbatimEnvironment").unwrap()
        );
        assert!(
            output.find(r"\@ifundefined{c@writerlisting}").unwrap()
                < output.find(r"\AtBeginDocument").unwrap()
        );
        assert!(
            output.find(r"\AtBeginDocument").unwrap()
                < output.find(r"\newenvironment{writercallout}").unwrap()
        );
    }

    #[test]
    fn cleveref_and_booktabs_follow_config_without_inventing_listing_counters()
    {
        let mut config = Config::default();
        config.latex.cleveref = true;
        config.latex.booktabs = false;
        let usage = Usage { table: true, ..Usage::default() };
        let output = preamble(&usage, &config);
        assert!(output.contains("\\usepackage{array}\n"));
        assert!(output.contains("\\usepackage{cleveref}\n"));
        assert!(!output.contains("\\usepackage{booktabs}"));
        assert!(!output.contains("\\usepackage{longtable}"));
        assert!(!output.contains("\\DeclareCaptionType"));
        assert!(!output.contains("\\crefname{writerlisting}"));
        assert!(!output.contains("\\Crefname{writerlisting}"));
        assert!(!output.contains("\\newcounter{none}"));
        assert!(!output.contains("\\DefineVerbatimEnvironment"));
    }

    #[test]
    fn configured_macros_are_math_gated_validated_and_kept_in_lexical_order() {
        let mut config = Config::default();
        config.math.katex_options.insert("macros".into(), json!({
            "\\Z": "#9/#1", "\\NoArgs": "\\alpha + {untouched}",
            "\\A": "\\frac{#2}{#1}", "\\Ignored": 1,
            "": "bad", "\\": "bad", "name": "bad", "\\bad_name": "bad",
            "\\Bad1": "bad", "\\α": "bad", "\\+": "bad", "\\\\Double": "bad",
        }));
        let original = config.clone();
        assert_eq!(preamble(&Usage::default(), &config), MINIMAL);
        let usage = Usage {
            math: true,
            secnumdepth: Some(5),
            tocdepth: Some(2),
            ..Usage::default()
        };
        let output = preamble(&usage, &config);
        assert!(output.ends_with(concat!(
            "\\setcounter{secnumdepth}{5}\n\\setcounter{tocdepth}{2}\n",
            "\\providecommand{\\A}[2]{\\frac{#2}{#1}}\n",
            "\\providecommand{\\NoArgs}{\\alpha + {untouched}}\n",
            "\\providecommand{\\Z}[9]{#9/#1}\n\\makeatother\n",
        )));
        assert!(!output.contains("bad"));
        assert!(!output.contains("Ignored"));
        assert_eq!(config, original);
    }
}
